#include <deque>
#include <exception>

// Custom exception type
class ReadEmptyStack : public std::exception {
public:
    const char* what() const throw() override { return "read empty stack"; }
};

template <class T>
T custom_pop(std::deque<T>& c) {
    if (c.empty()) {
        throw ReadEmptyStack(); // Precondition check
    }
    T elem(c.back());  // 1. Copy/Move (potential throw)
    c.pop_back();      // 2. Remove
    return elem;       // 3. Return
}
